export default Shop;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase/firebase';
import { doc, getDoc, collection, query, where, getDocs } from 'firebase/firestore';
import { Search, AlertCircle, Check, Home } from 'lucide-react';
import { Link, useLocation, useSearchParams, useParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { ORDER_STEPS, getStepIndex, getStatusStyle } from '../utils/orderStateMachine';

const TrackOrder = () => {
    const { orderId: paramOrderId } = useParams();
    const { currentUser } = useAuth();
    const [searchParams, setSearchParams] = useState({ orderId: '', email: '' });
    const [order, setOrder] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const location = useLocation();
    const [urlParams, setUrlParams] = useSearchParams();

    // Auto-fill and Search from URL or State
    useEffect(() => {
        const queryOrderId = urlParams.get('orderId');
        const queryEmail = urlParams.get('email');
        const stateOrderId = location.state?.orderId;
        const stateEmail = location.state?.email;

        // Priority: Route Param > Query Param > State
        const effectiveOrderId = paramOrderId || queryOrderId || stateOrderId;
        // Priority: Param > State > CurrentUser
        const effectiveEmail = queryEmail || stateEmail || currentUser?.email;

        if (effectiveOrderId) {
            // Update inputs even if we auto-fetch
            setSearchParams({
                orderId: effectiveOrderId,
                email: effectiveEmail || ''
            });

            // Auto-fetch if:
            // 1. We have both ID and Email
            // 2. We have ID and User is Logged In (we can check userId match)
            if (effectiveEmail || currentUser) {
                fetchOrder(effectiveOrderId, effectiveEmail);
            }
        }
    }, [location.state, urlParams, currentUser, paramOrderId, fetchOrder]);

    // Independent Fetcher to allow useEffect to call it
    const fetchOrder = React.useCallback(async (oid, uemail) => {
        setLoading(true);
        setError(null);
        try {
            // 1. Try finding by matching 'orderId' field
            const q = query(
                collection(db, "orders"),
                where("orderId", "==", oid)
            );
            const querySnapshot = await getDocs(q);

            let docSnap = null;
            if (!querySnapshot.empty) {
                docSnap = querySnapshot.docs[0];
            } else {
                // 2. Fallback: Doc ID
                const docRef = doc(db, "orders", oid);
                const ds = await getDoc(docRef);
                if (ds.exists()) docSnap = ds;
            }

            if (docSnap && docSnap.exists()) {
                const data = docSnap.data();

                // AUTH CHECK:
                // 1. If Logged In & User ID matches -> Allow
                // 2. Else -> Require Email Match
                const isOwner = currentUser && data.userId === currentUser.uid;
                const orderEmail = (data.userEmail || data.shippingAddress?.email || data.email || '').toLowerCase();
                const searchEmail = (uemail || '').toLowerCase();

                if (isOwner || (searchEmail && orderEmail === searchEmail)) {
                    setOrder({ id: docSnap.id, ...data });
                } else {
                    setError("Order found, but you are not authorized to view it. Verification failed.");
                }
            } else {
                setError("Order not found.");
            }
        } catch (err) {
            setError("Failed to track order.");
        } finally {
            setLoading(false);
        }
    }, [currentUser]);

    // Trigger Fetch if params are present on mount
    useEffect(() => {
        const oid = urlParams.get('orderId') || location.state?.orderId;
        const email = urlParams.get('email') || location.state?.email;

        if (oid && (email || currentUser)) {
            // Re-run logic will be handled by the main useEffect above due to deps
            // checking currentUser there is safer.
        }
    }, [urlParams, location.state, currentUser]); // Run once on mount (reload/nav)

    const handleSearch = async (e) => {
        if (e) e.preventDefault();
        setError(null);
        setOrder(null);
        setLoading(true);

        const orderIdToSearch = searchParams.orderId;
        const emailToSearch = searchParams.email;

        // Update URL to make it shareable/persistent if triggered manually
        setUrlParams({ orderId: orderIdToSearch, email: emailToSearch });

        try {
            // Trim and clean input
            const orderId = orderIdToSearch.trim();
            const email = emailToSearch.trim().toLowerCase();

            if (!orderId) {
                throw new Error("Please enter an Order ID.");
            }
            if (!email && !currentUser) {
                throw new Error("Please enter Email Address.");
            }

            // 1. Try finding by matching 'orderId' field (New readable ID)
            const q = query(
                collection(db, "orders"),
                where("orderId", "==", orderId)
            );
            const querySnapshot = await getDocs(q);

            let docSnap = null;
            if (!querySnapshot.empty) {
                docSnap = querySnapshot.docs[0];
            } else {
                // 2. Fallback: Try finding by Document ID (Old style)
                const docRef = doc(db, "orders", orderId);
                const ds = await getDoc(docRef);
                if (ds.exists()) {
                    docSnap = ds;
                }
            }

            if (docSnap && docSnap.exists()) {
                const data = docSnap.data();

                const isOwner = currentUser && data.userId === currentUser.uid;
                const orderEmail = (data.userEmail || data.shippingAddress?.email || data.email || '').toLowerCase();

                if (isOwner || (email && orderEmail === email)) {
                    setOrder({ id: docSnap.id, ...data });
                } else {
                    setError("Order found, but you are not authorized to view it.");
                }
            } else {
                setError("Order not found. Please check the ID.");
            }
        } catch (err) {
            setError(err.message || "Failed to track order.");
        } finally {
            setLoading(false);
        }
    };

    const steps = ORDER_STEPS;

    return (
        <div className="w-full pb-8 bg-slate-50 bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px]">
            <div className="max-w-3xl mx-auto">

                <div className="text-center mb-10">
                    <h1 className="text-4xl font-black text-gray-900 mb-4 tracking-tight">Track Your Order</h1>
                    <p className="text-gray-500 font-medium">Enter your Order ID and Email to see real-time updates.</p>
                </div>

                {/* Search Form */}
                <div className="frosted-paper p-8 rounded-3xl border border-white/60 shadow-xl shadow-orange-500/5 mb-10 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-orange-100 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

                    <form onSubmit={handleSearch} className="relative z-10 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-gray-500 uppercase tracking-wide ml-1">Order ID</label>
                                <input
                                    type="text"
                                    placeholder="e.g. 7A2B9C..."
                                    value={searchParams.orderId}
                                    onChange={e => setSearchParams({ ...searchParams, orderId: e.target.value })}
                                    className="w-full bg-white border border-gray-100 rounded-xl px-4 py-3 font-bold text-gray-900 outline-none focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 transition-all placeholder:font-normal"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-gray-500 uppercase tracking-wide ml-1">Email Address</label>
                                <input
                                    type="email"
                                    placeholder="used during checkout"
                                    value={searchParams.email}
                                    onChange={e => setSearchParams({ ...searchParams, email: e.target.value })}
                                    className="w-full bg-white border border-gray-100 rounded-xl px-4 py-3 font-bold text-gray-900 outline-none focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 transition-all placeholder:font-normal"
                                />
                            </div>
                        </div>
                        <button
                            type="submit"
                            disabled={loading}
                            className="w-full bg-gray-900 text-white font-bold py-4 rounded-xl shadow-lg hover:shadow-xl hover:bg-black transition-all active:scale-[0.98] flex items-center justify-center gap-2"
                        >
                            {loading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Search size={20} />}
                            Track Order
                        </button>
                    </form>
                </div>

                {/* Error State */}
                {error && (
                    <div className="animate-fade-in-up bg-red-50 text-red-600 p-4 rounded-2xl flex items-center gap-3 border border-red-100 mb-8 font-bold">
                        <AlertCircle size={20} />
                        {error}
                    </div>
                )}

                {/* Order Result */}
                {order && (
                    <div className="animate-fade-in-up space-y-6">
                        {/* Status Card */}
                        <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl">
                            <div className="flex justify-between items-center mb-8">
                                <div>
                                    <h2 className="text-xl font-black text-gray-900">Order Status</h2>
                                    <p className="text-sm text-gray-500 font-bold mt-1">Last updated: {new Date().toLocaleTimeString()}</p>
                                </div>
                                <div className={`px-4 py-2 rounded-full text-xs font-black uppercase tracking-wide ${getStatusStyle(order.status).bg} ${getStatusStyle(order.status).text}`}>
                                    {order.status || 'Processing'}
                                </div>
                            </div>

                            {/* Stepper */}
                            <div className="relative mb-8">
                                <div className="absolute top-3 left-0 w-full h-1 bg-gray-100 rounded-full"></div>
                                <div
                                    className="absolute top-3 left-0 h-1 bg-green-500 rounded-full transition-all duration-1000"
                                    style={{ width: `${Math.min((getStepIndex(order.status) / (steps.length - 1)) * 100, 100)}%` }}
                                ></div>
                                <div className="relative z-10 flex justify-between">
                                    {steps.map((step, index) => {
                                        const isCompleted = index <= getStepIndex(order.status);
                                        return (
                                            <div key={index} className="flex flex-col items-center">
                                                <div className={`w-7 h-7 rounded-full flex items-center justify-center border-2 transition-all duration-300 bg-white ${isCompleted ? 'border-green-500 text-green-500' : 'border-gray-200 text-gray-300'}`}>
                                                    {isCompleted && <Check size={14} strokeWidth={4} />}
                                                </div>
                                                <p className={`text-[10px] md:text-xs font-bold mt-3 uppercase tracking-wider ${isCompleted ? 'text-green-600' : 'text-gray-400'}`}>{step.label}</p>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>

                            {/* Order Details */}
                            <div className="border-t border-gray-100 pt-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-3">Items</h3>
                                    <div className="space-y-3">
                                        {order.items?.map((item, i) => (
                                            <div key={i} className="flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-lg bg-gray-100 overflow-hidden flex-shrink-0">
                                                    <img src={item.image || item.imageUrl} className="w-full h-full object-cover" alt="" />
                                                </div>
                                                <div className="min-w-0">
                                                    <p className="text-sm font-bold text-gray-900 truncate">{item.name}</p>
                                                    <p className="text-xs text-gray-500">Qty: {item.quantity}</p>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                                <div className="md:text-right">
                                    <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-3">Recipient</h3>
                                    <p className="font-bold text-gray-900">{order.address?.fullName}</p>
                                    <p className="text-xs text-gray-500">{order.address?.city}, {order.address?.pincode}</p>
                                    <div className="mt-4">
                                        <p className="text-xs font-bold text-gray-400 uppercase tracking-wide">Total Paid</p>
                                        <p className="text-xl font-black text-gray-900">Γé╣{order.total}</p>
                                        <Link to={`/order/${order.id}`} className="text-xs text-orange-600 font-bold hover:underline mt-1 block">
                                            View Full Receipt
                                        </Link>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="flex justify-center">
                            <Link to="/" className="text-gray-400 hover:text-orange-600 font-bold flex items-center gap-2 transition-colors">
                                <Home size={18} /> Return Home
                            </Link>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default TrackOrder;

import React from 'react';
import { useWishlist } from '../context/WishlistContext';
import { useCart } from '../context/CartContext';
import { Trash2, ShoppingCart, Heart, ArrowRight, Home } from 'lucide-react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import Button from '../components/Button';
import Card from '../components/common/Card';

const Wishlist = () => {
    const { wishlistItems, removeFromWishlist } = useWishlist();
    const { addToCart } = useCart();

    const handleMoveToCart = (product) => {
        addToCart(product);
        removeFromWishlist(product.id);
    };

    if (wishlistItems.length === 0) {
        return (
            <div className="min-h-[60vh] flex flex-col items-center justify-center p-4 bg-slate-50">
                <div className="w-24 h-24 bg-red-50 rounded-full flex items-center justify-center mb-6">
                    <Heart size={48} className="text-red-300 fill-red-100" />
                </div>
                <h2 className="text-2xl font-bold text-gray-900 mb-2">Your Wishlist is Empty</h2>
                <p className="text-gray-500 mb-8 text-center max-w-sm">
                    Looks like you haven't saved any items yet. Explore our products and save your favorites!
                </p>
                <Link to="/">
                    <Button variant="primary" size="lg" className="gap-2">
                        <Home size={20} /> Start Shopping
                    </Button>
                </Link>
            </div>
        );
    }

    return (
        <div className="w-full pb-8 bg-slate-50 page-enter">
            <div className="max-w-7xl mx-auto">

                {/* Header */}
                <div className="flex justify-between items-center mb-8">
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900">My Wishlist</h1>
                        <p className="text-gray-500 mt-1">{wishlistItems.length} items saved</p>
                    </div>
                    <Link
                        to="/"
                        className="flex items-center gap-2 text-gray-500 hover:text-orange-600 font-medium transition-colors"
                    >
                        <Home size={18} /> Home
                    </Link>
                </div>

                {/* Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {wishlistItems.map((item) => (
                        <motion.div
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 0.9 }}
                            key={item.id}
                            layout
                        >
                            <Card className="h-full flex flex-col p-0 overflow-hidden group hover:shadow-md transition-all border-gray-100 rounded-3xl">
                                <div className="relative aspect-square overflow-hidden bg-gray-50">
                                    <img
                                        src={item.image || item.imageUrl || item.img || 'https://placehold.co/400x400'}
                                        alt={item.name}
                                        loading="lazy"
                                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                                    />
                                    <Button
                                        variant="white"
                                        size="icon-sm"
                                        onClick={() => removeFromWishlist(item.id)}
                                        className="absolute top-3 right-3 text-red-500 hover:bg-red-50 shadow-sm"
                                        title="Remove from Wishlist"
                                    >
                                        <Trash2 size={18} />
                                    </Button>
                                </div>

                                <div className="p-5 flex flex-col flex-grow">
                                    <div className="mb-4">
                                        <p className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-1">{item.category}</p>
                                        <h3 className="font-bold text-gray-900 leading-tight truncate">{item.name}</h3>
                                    </div>

                                    <div className="mt-auto flex items-center justify-between gap-4">
                                        <span className="text-xl font-bold text-gray-900">Γé╣{item.price}</span>
                                        <Button
                                            onClick={() => handleMoveToCart(item)}
                                            variant="secondary"
                                            size="sm"
                                            className="flex-1"
                                        >
                                            <ShoppingCart size={16} className="mr-2" />
                                            Move to Cart
                                        </Button>
                                    </div>
                                </div>
                            </Card>
                        </motion.div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Wishlist;

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { doc, getDoc, updateDoc, increment } from 'firebase/firestore';
import { db } from '../../firebase/firebase';
import { ArrowLeft, Package, User, MapPin, Phone, CreditCard, ChevronDown, AlertTriangle, CheckCircle, Truck, Clock, XCircle } from 'lucide-react';
import Button from '../../components/Button';
import Card from '../../components/common/Card';

const AdminOrderDetails = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [order, setOrder] = useState(null);
    const [loading, setLoading] = useState(true);
    const [updating, setUpdating] = useState(false);

    useEffect(() => {
        const fetchOrder = async () => {
            try {
                const docRef = doc(db, 'orders', id);
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    setOrder({ id: docSnap.id, ...docSnap.data() });
                }
            } catch (error) {
                console.error("Error fetching order:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchOrder();
    }, [id]);

    const handleStatusChange = async (newStatus) => {
        setUpdating(true);
        try {
            await updateDoc(doc(db, 'orders', id), { status: newStatus });
            setOrder(prev => ({ ...prev, status: newStatus }));
        } catch (error) {
            console.error("Error updating status:", error);
            alert("Failed to update status");
        } finally {
            setUpdating(false);
        }
    };

    const getStatusColor = (status) => {
        switch (status) {
            case 'Delivered': return 'bg-green-100 text-green-700 border-green-200';
            case 'Cancelled': return 'bg-red-100 text-red-700 border-red-200';
            case 'Shipped': return 'bg-blue-100 text-blue-700 border-blue-200';
            case 'Processing': return 'bg-orange-100 text-orange-700 border-orange-200';
            default: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
        }
    };

    if (loading) return (
        <div className="flex h-[60vh] items-center justify-center">
            <div className="animate-spin rounded-full h-12 w-12 border-4 border-orange-200 border-t-orange-600"></div>
        </div>
    );

    if (!order) return <div className="text-center p-10 font-bold text-gray-500">Order not found</div>;

    return (
        <div className="max-w-5xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex items-center gap-4">
                    <Button
                        variant="white"
                        size="icon"
                        onClick={() => navigate('/admin/orders')}
                        className="shadow-sm border-gray-200 text-gray-500 hover:text-gray-900"
                    >
                        <ArrowLeft size={20} />
                    </Button>
                    <div>
                        <div className="flex items-center gap-3">
                            <h1 className="text-3xl font-black text-gray-900 tracking-tight">Order #{order.orderId || order.id.slice(0, 8)}</h1>
                            <span className={`px-3 py-1 rounded-full text-xs font-black uppercase tracking-wide border ${getStatusColor(order.status)}`}>
                                {order.status}
                            </span>
                        </div>
                        <p className="text-sm font-bold text-gray-400 mt-1">
                            Placed on {order.createdAt ? new Date(order.createdAt.seconds * 1000).toLocaleString() : 'N/A'}
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-3 bg-white p-1.5 rounded-2xl border border-gray-100 shadow-sm">
                    {['Pending', 'Processing', 'Shipped', 'Delivered', 'Cancelled'].map((status) => (
                        <button
                            key={status}
                            onClick={() => handleStatusChange(status)}
                            disabled={updating}
                            className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wide transition-all ${order.status === status
                                ? 'bg-gray-900 text-white shadow-md scale-105'
                                : 'text-gray-500 hover:bg-gray-50'
                                }`}
                        >
                            {status}
                        </button>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Left: Order Items */}
                <div className="md:col-span-2 space-y-6">
                    <Card className="p-0 overflow-hidden border-orange-100/50">
                        <div className="px-6 py-4 border-b border-gray-100 bg-orange-50/30 flex items-center gap-2">
                            <Package className="text-orange-500" size={20} />
                            <h2 className="font-black text-gray-900">Order Items</h2>
                        </div>
                        <div className="p-6 space-y-6">
                            {order.items?.map((item, index) => (
                                <div key={index} className="flex gap-4 group">
                                    <div className="w-20 h-20 rounded-xl bg-gray-100 overflow-hidden border border-gray-200 shrink-0">
                                        <img src={item.image || item.imageUrl || 'https://placehold.co/100'} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h3 className="font-bold text-gray-900 text-lg truncate">{item.name}</h3>
                                        <p className="text-sm font-medium text-gray-500">Category: {item.category}</p>
                                        <div className="flex items-center gap-4 mt-2">
                                            <span className="text-xs font-bold bg-gray-100 text-gray-600 px-2 py-1 rounded-lg">Qty: {item.quantity || 1}</span>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="font-black text-gray-900 text-lg">Γé╣{item.price * (item.quantity || 1)}</p>
                                        <p className="text-xs text-gray-400 font-medium">Γé╣{item.price} / unit</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="bg-gray-50 p-6 flex justify-between items-center border-t border-gray-100">
                            <span className="font-bold text-gray-500 uppercase tracking-widest text-xs">Total Order Value</span>
                            <span className="text-3xl font-black text-gray-900 tracking-tight">Γé╣{order.total}</span>
                        </div>
                    </Card>
                </div>

                {/* Right: Customer Info */}
                <div className="space-y-6">
                    <Card className="p-6 space-y-6">
                        <div>
                            <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <User size={16} /> Customer Details
                            </h2>
                            <div className="flex items-center gap-4 mb-4">
                                <div className="w-12 h-12 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center font-black text-lg">
                                    {(order.customer?.name || order.address?.fullName || "G")[0]}
                                </div>
                                <div>
                                    <p className="font-bold text-gray-900">{order.customer?.name || order.address?.fullName || "Guest User"}</p>
                                    <p className="text-xs font-bold text-gray-500">{order.customer?.email || order.userEmail || order.email}</p>
                                </div>
                            </div>
                            {order.address?.phoneNumber && (
                                <div className="flex items-center gap-3 text-sm font-bold text-gray-600 bg-gray-50 p-3 rounded-xl">
                                    <Phone size={16} /> {order.address.phoneNumber}
                                </div>
                            )}
                        </div>

                        <div className="border-t border-gray-100 pt-6">
                            <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <MapPin size={16} /> Shipping Address
                            </h2>
                            <p className="text-sm font-medium text-gray-700 leading-relaxed bg-gray-50 p-4 rounded-xl border border-gray-100">
                                {order.address ? (
                                    <>
                                        {order.address.addressLine1}, <br />
                                        {order.address.city}, {order.address.state} <br />
                                        {order.address.pincode}
                                    </>
                                ) : "No address provided"}
                            </p>
                        </div>

                        <div className="border-t border-gray-100 pt-6">
                            <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <CreditCard size={16} /> Payment Info
                            </h2>
                            <div className={`p-4 rounded-xl border flex items-center justify-between ${order.isPaid ? 'bg-green-50 border-green-100' : 'bg-orange-50 border-orange-100'}`}>
                                <span className={`text-xs font-black uppercase ${order.isPaid ? 'text-green-700' : 'text-orange-700'}`}>
                                    {order.isPaid ? 'Paid Online' : 'Cash on Delivery'}
                                </span>
                                {order.isPaid ? <CheckCircle size={18} className="text-green-600" /> : <Clock size={18} className="text-orange-600" />}
                            </div>
                        </div>
                    </Card>

                    {/* Quick Actions */}
                    <Card className="p-6">
                        <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4">Quick Actions</h2>
                        <Button
                            onClick={() => window.print()}
                            variant="secondary"
                            className="w-full mb-3"
                        >
                            Print Invoice
                        </Button>
                        {order.status !== 'Cancelled' && (
                            <Button
                                onClick={() => {
                                    if (window.confirm('Are you sure you want to cancel this order?')) {
                                        handleStatusChange('Cancelled');
                                    }
                                }}
                                className="w-full bg-red-50 text-red-600 hover:bg-red-100 border-red-100"
                            >
                                Cancel Order
                            </Button>
                        )}
                    </Card>
                </div>
            </div>
        </div>
    );
};

export default AdminOrderDetails;

import React, { useState, useEffect } from 'react';
import { useRoadmap } from '../../hooks/useRoadmap';
import { useFeedback } from '../../hooks/useFeedback';
import { generateRoadmap } from '../../services/aiService';
import { Loader2, Sparkles, Map, AlertCircle, CheckCircle2, Clock } from 'lucide-react';

const AdminRoadmap = () => {
    const { fetchRoadmap, saveRoadmapItems, updateItemStatus } = useRoadmap();
    const { getFeedback } = useFeedback();
    const [roadmap, setRoadmap] = useState([]);
    const [loading, setLoading] = useState(true);
    const [generating, setGenerating] = useState(false);

    const loadData = React.useCallback(async () => {
        setLoading(true);
        const data = await fetchRoadmap();
        setRoadmap(data);
        setLoading(false);
    }, [fetchRoadmap]);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const handleGenerate = async () => {
        setGenerating(true);
        try {
            // 1. Get Feedback
            const feedback = await getFeedback();
            // 2. Generate Roadmap via AI
            const newItems = await generateRoadmap(feedback);
            // 3. Save to DB
            if (newItems.length > 0) {
                await saveRoadmapItems(newItems);
                await loadData(); // Reload to see new items
            } else {
                alert("AI couldn't generate any new items (or no feedback found).");
            }
        } catch (error) {
            console.error(error);
            alert("Failed to generate roadmap.");
        } finally {
            setGenerating(false);
        }
    };

    const handleStatusChange = async (id, status) => {
        await updateItemStatus(id, status);
        // Optimistic update locally
        setRoadmap(prev => prev.map(item => item.id === id ? { ...item, status } : item));
    };

    const PriorityColumn = ({ title, priority, icon: Icon, color }) => {
        const items = roadmap.filter(i => i.priority === priority);
        return (
            <div className="flex-1 min-w-[300px] bg-slate-50/50 rounded-3xl p-4 border border-slate-100 flex flex-col">
                <div className={`flex items-center gap-2 mb-4 p-2 rounded-xl ${color} bg-opacity-10 text-${color.split('-')[1]}-600`}>
                    <Icon size={18} className={`text-${color.split('-')[1]}-500`} />
                    <h3 className="font-bold text-sm uppercase tracking-wider">{title}</h3>
                    <span className="ml-auto bg-white px-2 py-0.5 rounded-md text-xs font-black shadow-sm">{items.length}</span>
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 scrollbar-thin">
                    {items.length === 0 && (
                        <div className="text-center py-10 text-gray-400 text-sm border-2 border-dashed border-gray-100 rounded-xl">
                            No {title.toLowerCase()} items.
                        </div>
                    )}
                    {items.map(item => (
                        <div key={item.id} className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow group relative">
                            {/* Status Badge */}
                            <div className="flex justify-between items-start mb-2">
                                <span className={`text-[10px] font-bold px-2 py-1 rounded-md uppercase tracking-wide
                                    ${item.status === 'Completed' ? 'bg-green-100 text-green-700' :
                                        item.status === 'In Progress' ? 'bg-blue-100 text-blue-700' :
                                            'bg-gray-100 text-gray-600'}`}>
                                    {item.status}
                                </span>
                                <select
                                    className="opacity-0 group-hover:opacity-100 absolute top-2 right-2 text-xs border border-gray-200 rounded p-1"
                                    value={item.status}
                                    onChange={(e) => handleStatusChange(item.id, e.target.value)}
                                >
                                    <option value="Planned">Planned</option>
                                    <option value="In Progress">In Progress</option>
                                    <option value="Completed">Completed</option>
                                </select>
                            </div>

                            <h4 className="font-bold text-gray-800 text-sm mb-1">{item.title}</h4>
                            <p className="text-xs text-slate-500 mb-3 line-clamp-2">{item.reason}</p>

                            <div className="flex items-center gap-2 text-[10px] font-bold text-green-600 bg-green-50 px-2 py-1 rounded w-fit">
                                <Sparkles size={10} />
                                {item.impact}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    return (
        <div className="h-[calc(100vh-100px)] flex flex-col space-y-6 pb-4 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 flex items-center gap-2">
                        Product Roadmap <Map className="text-orange-500" />
                    </h1>
